# Ejecutar desde la carpeta del proyecto, donde esta package.json.
$ErrorActionPreference = 'Stop'
$patchPaths = @()
function Test-Patch($root, $patch, $reverse) {
    $ErrorActionPreference = 'Continue'
    if ($reverse) {
        $diagnostic = & git -C $root apply --reverse --check --ignore-space-change --whitespace=nowarn $patch 2>&1
    } else {
        $diagnostic = & git -C $root apply --check --ignore-space-change --whitespace=nowarn $patch 2>&1
    }
    return ($LASTEXITCODE -eq 0)
}
try {
    if (-not (Get-Command git -ErrorAction SilentlyContinue)) { throw 'No se encontro Git. Ejecuta este parche en una terminal con Git instalado.' }
    if (-not (Test-Path -LiteralPath 'src/views/PagosView.vue')) { throw 'Abre PowerShell en la carpeta de tu proyecto, donde estan package.json y src.' }
    $root = (Get-Location).Path
    $encoded = @('', '')
    foreach ($value in $encoded) {
        $temp = [System.IO.Path]::GetTempFileName()
        $patchPaths += $temp
        [System.IO.File]::WriteAllBytes($temp, [System.Convert]::FromBase64String($value))
    }
    $chosen = $null
    foreach ($patch in $patchPaths) {
        if (Test-Patch $root $patch $false) { $chosen = $patch; break }
    }
    if ($null -eq $chosen) {
        foreach ($patch in $patchPaths) {
            if (Test-Patch $root $patch $true) {
                Write-Host 'El parche de pagos por unidad y en bloque ya esta aplicado.' -ForegroundColor Green
                exit 0
            }
        }
        throw 'El proyecto tiene cambios incompatibles con las versiones del parche. No se modifico ningun archivo. Comparte el proyecto actualizado para adaptar el parche.'
    }
    & git -C $root apply --ignore-space-change --whitespace=nowarn $chosen
    if ($LASTEXITCODE -ne 0) { throw 'Git no pudo aplicar el parche. Revisa el mensaje anterior.' }
    Write-Host 'Parche aplicado: pagos por unidad y en bloque.' -ForegroundColor Green
    Write-Host 'Ahora puedes probar la aplicacion y hacer git add, commit y push.'
} catch {
    Write-Host $_.Exception.Message -ForegroundColor Red
    exit 1
} finally {
    foreach ($temp in $patchPaths) {
        if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Force }
    }
}
